from pathlib import Path
import re

p=Path('content/english/shared/pedagogical-orchestrator-v1.js')
s=p.read_text()
repls={
'buildTargetShooterPayload': '''  function buildTargetShooterPayload(source,analysis={},context={}){const q=clone(source),alts=alternatives(q),priorCfg=q?.metadata?.targetShooter||{},prior=Array.isArray(priorCfg.items)?clone(priorCfg.items):[],answer=String(answerValue(q)??"");q.delivery={...(q.delivery||{}),mechanic:"target-shooter"};q.metadata={...(q.metadata||{}),targetShooter:{...priorCfg,audioText:text(priorCfg.audioText||q?.media?.audio?.text||q?.audio?.text||q?.metadata?.audioText||q?.instruction),mode:text(priorCfg.mode,"audio-to-image"),shape:text(priorCfg.shape,"balloon"),correctIds:answer?[answer]:clone(priorCfg.correctIds||[]),items:alts.map((a,i)=>({...optionFrom(a,i),...(prior.find(p=>String(p.id)===String(a.id))||{}),id:text(a.id,String.fromCharCode(65+i))})),difficulty:{...(priorCfg.difficulty||{}),targetSize:Math.max(170,Number(priorCfg.difficulty?.targetSize)||0),timeLimitMs:0,timerMode:"none"}}};return markRecovery(q,analysis,context)}\n''',
'buildMatchingPayload': '''  function buildMatchingPayload(source,analysis={},context={}){const q=clone(source),alts=alternatives(q),current=q?.metadata?.matching||{},stimulus=stimulusFrom(q)||{},answer=String(answerValue(q)??""),native=Array.isArray(current.leftItems)&&Array.isArray(current.rightItems)&&Array.isArray(current.pairs);q.delivery={...(q.delivery||{}),mechanic:"matching"};let config;if(native){config=clone(current)}else{const assets={...(current.assets||{})};const left={id:"stimulus"};if(stimulus.imageUrl){assets.stimulus=stimulus.imageUrl;left.imageAssetKey="stimulus";left.alt=text(stimulus.alt||q.metadata?.contextAlt||q.prompt,"Contexto visual")}else{left.spokenText=text(q?.audio?.text||q?.media?.audio?.text||q?.metadata?.audioText||q?.instruction||q?.prompt,"Listen");left.speechLocale="en-US";left.audioDescription="Ouvir novamente"}const right=alts.map((a,i)=>{const o=optionFrom(a,i);return{id:`answer-${o.id}`,spokenText:text(o.spokenText||o.text||o.label),speechLocale:text(o.speechLocale,"en-US"),audioDescription:`Ouvir opção ${i+1}`}});config={...current,mode:stimulus.imageUrl?"image-audio":"audio-audio",leftTitle:stimulus.imageUrl?"Observe":"Ouça",rightTitle:"Ouça e relacione",assets,leftItems:[left],rightItems:right,pairs:answer?[{leftId:"stimulus",rightId:`answer-${answer}`}]:[],behavior:{...(current.behavior||{}),lockLeftOrder:true,shuffleRight:true,connectionMode:"1x1",interactionMode:"smart",lockCorrectPairsOnRetry:true,allowUnpairedDistractors:true}}}q.metadata={...(q.metadata||{}),matching:config};return markRecovery(q,analysis,context)}\n''',
'buildDragDropPayload': '''  function buildDragDropPayload(source,analysis={},context={}){const profile=getProfile(context.yearProfile||analysis.yearProfile),role=text(analysis.dragSemanticRole),reason=text(analysis.dragSemanticReason||analysis.dragValueJustification);if(profile.year<=2&&(!DRAG_ROLES.has(role)||!reason))throw new Error(`DRAG_SEMANTIC_REASON_REQUIRED:${source?.id||"unknown"}`);if(!role)throw new Error(`DRAG_SEMANTIC_ROLE_REQUIRED:${source?.id||"unknown"}`);const q=clone(source);if(!Array.isArray(q?.payload?.items)||!Array.isArray(q?.payload?.targets)||!q.payload.targets.length)throw new Error(`DRAG_NATIVE_PAYLOAD_REQUIRED:${source?.id||"unknown"}`);q.delivery={...(q.delivery||{}),mechanic:"drag-drop"};q.metadata={...(q.metadata||{}),dragSemanticRole:role,dragSemanticReason:reason};q.payload={...q.payload,mode:text(q.payload.mode,role)};return markRecovery(q,analysis,{...context,yearProfile:profile.id})}\n'''
}
for name,new in repls.items():
    pattern=rf'^  function {name}\([^\n]*$'
    s2,n=re.subn(pattern,new.rstrip('\n'),s,flags=re.M)
    if n!=1: raise SystemExit(f'{name}: expected 1 replacement, got {n}')
    s=s2
p.write_text(s)

t=Path('test/systemic/y1-y2-early-literacy-router.mjs')
x=t.read_text()
x=x.replace('assert.equal(target.metadata.targetShooter.items.length,3);\nassert.equal(target.metadata.targetShooter.difficulty.timerMode,"none");', 'assert.equal(target.metadata.targetShooter.items.length,3);\nassert.deepEqual(target.metadata.targetShooter.correctIds,["A"]);\nassert.equal(target.metadata.targetShooter.difficulty.timerMode,"none");\nassert.equal(target.metadata.targetShooter.difficulty.timeLimitMs,0);')
x=x.replace('assert.equal(matching.metadata.matching.options.length,3);', 'assert.equal(matching.metadata.matching.leftItems.length,1);\nassert.equal(matching.metadata.matching.rightItems.length,3);\nassert.deepEqual(matching.metadata.matching.pairs,[{leftId:"stimulus",rightId:"answer-A"}]);')
x=x.replace('const drag=O.buildDragDropPayload(source,semanticDrag,{yearProfile:"Y2_FOUNDATIONAL_LITERACY"});', 'const semanticDragSource={...source,payload:{mode:"classification",items:[{id:"A",label:"cat",targetId:"wild"}],targets:[{id:"wild",label:"Wild",capacity:3}]}};\nconst drag=O.buildDragDropPayload(semanticDragSource,semanticDrag,{yearProfile:"Y2_FOUNDATIONAL_LITERACY"});')
x=x.replace('assert.equal(drag.metadata.dragSemanticRole,"classification");', 'assert.equal(drag.metadata.dragSemanticRole,"classification");\nassert.equal(drag.payload.mode,"classification");\nassert.throws(()=>O.buildDragDropPayload(source,semanticDrag,{yearProfile:"Y2_FOUNDATIONAL_LITERACY"}),/DRAG_NATIVE_PAYLOAD_REQUIRED/);')
t.write_text(x)
